import { redirect } from "react-router-dom"

export const requireAuth = async (request) => {
  const pathname = new URL(request.url).pathname
  const isLoggedIn = localStorage.getItem("loggedin")
  
  if (!isLoggedIn) {
    throw redirect("/login?message=You must log in first.")
  }
  return null
}

export function checker(array, target) {
  if (target.length === 0) {
    return false
  }
  return target.every(value => array.includes(value));
}

export function sanitizeString(str) {
  str = str.replace(/[^a-zA-Z]/g, "");
  return str.trim();
}

export function highlightString(str, words) {
  words.array.forEach(word => {
    str = str.replace(word, `<`)
  });
}

export function highlightWords(text, highlights) {
  const colors = [
    {
      words: ["if", "then", "else", "elseif", "end", "for", " in ", "do", "while", "repeat", "until", "function", "return", "break"],
      style: { color: '#BA7FB6' }
    },
    {
      words: ["nil", "true", "false", "local"],
      style: { color: '#2461C0' }
    },
    {
      words: ["(", ")"],
      style: { color: '#CFCB10' }
    },
    {
      words: highlights,
      style: { color: '#D0D0A1' }
    },
    {
      words: ["\n"],
      style: { color: 'white', fontWeight: "500" }
    }
  ];

  const combinedWords = colors.flatMap(color => color.words);
  const regex = new RegExp(`(${combinedWords.join('|')})`, 'g');

  const highlightedText = text.split(regex).map((part, index) => {
    const style = colors.find(color => color.words.includes(part))?.style;
    
    if (style) {
      return (
        <span key={index} style={style}>
          {part}
        </span>
      );
    }

    if (part) {
      return <span key={index}>{part}</span>;
    }
  });

  return (
    <div style={{ whiteSpace: 'pre-wrap' }}>
      {highlightedText}
    </div>
  );
}