import React, { useContext } from "react"
import {
    Link,
    NavLink,
    navigate,
    useNavigate
} from "react-router-dom"
import externalLinkIcon from "../../assets/images/external-link.png"
import backIcon from "../../assets/images/back-icon.png"
import { AppState } from "../.."

export default function Tag({ tags, name, description, inputs, outputs, code, deprecateNotice, status, example, table, noApi, isPopup, patch, page, link, expLink, section }) {
    const { apiPages, tagCategories, selectedTags, updateTags, tdPatch } = useContext(AppState);
    let navigate = useNavigate()
    const hasPatch = patch !== null
    const experimental = hasPatch && patch > tdPatch
    const popupStyle = isPopup 
        ? `"header header header back"
        "example example example back"`
        : `"header header header header"
        "example example example example"`

    const funcStyle = {
        gridTemplateAreas: `
            ${popupStyle}
            "arguments arguments arguments arguments"
            "description description description description"
            "table table table table"
            "code code code code"
            "tags tags tags tags"
        `
    }

    console.log(funcStyle)

    tags?.sort()
    
    const tagElements = tags?.map((tag, index) => {
        const selected = selectedTags.value.includes(tag)
        return (
            <span
                key={index}
                className={`func--prev ${selected ? "red" : ""}`}
                onClick={() => updateTags(tag)}
            >
                {tag}
            </span>
        )
    })

    const inputsExamples = inputs.map((arg, index) => (
        <span key={index} className="func--argument courier">
            {arg.optional ? `[${arg.name}]` : arg.name}
        </span>
    ))

    const inputsList = inputs.map((arg, index) => (
        <p key={index} className="func--argument courier">{arg.name}
            <inline className="func--text" style={{ marginLeft: "5px"}} >
                (<inline className="courier">
                    {arg.type}
                </inline>
                {arg.optional &&  ", optional"}
                ) - {arg.description}
            </inline>
        </p>
    ))

    const exampleArguments = (inputs[0] 
        ? <span className="func--argument">
            <span>=</span>
            {inputsExamples}
        </span> 
        : ""
    )

    const headerText = isPopup
        ? <inline className="func--header-nolink" >{name}</inline>
        : <NavLink
            to={`/api/${page}/${name}`}
        >
            {name}
        </NavLink>

    const headerElement = (
        <div className="func--header">
            {headerText}
            {experimental && <inline className="func--text func--experimental">{`Experimental`}</inline>}
            {status && <inline className="func--text func--status">{` (${status})`}</inline>}
        </div>)
    
    const backElement = isPopup
        ? (<div
            className="func--back"
            onMouseUp={()=>{navigate(`/api/${page}`)}}
            onTouchEnd={()=>{navigate(`/api/${page}`)}}
        >
            <img
                className="func--back-image"
                src={backIcon}
                alt="Back"
            />
        </div>)
        : ""

    console.log(page)

    const exampleElement = (
        <div className="func--example func--func courier">
            {name}
            {exampleArguments}
        </div>)

    const descriptionElement = (
        <div className="func--description">
            {deprecateNotice && <p className="red bold">This function will be deprecated in the next update!</p>}
            {description && <p className="func--text">{description}</p>}
        </div>)

    const tagField = (
        <div className="func--flex func--tags">
            {tagElements}

            {!noApi
                ? <inline className={`func--prev`}>
                    <Link 
                        to={`${experimental ? expLink : link}${name}`} 
                        target="_blank" 
                        rel="noopener noreferrer" 
                        className="api-link"
                    >
                        {experimental ? "Experimental API" : `${section} API`}
                        <img src={externalLinkIcon} height="10px" align="center middle" style={{ marginLeft: "5px", color: "" }} />
                    </Link>
                </inline>
                : ""}
        </div>
    )

    const argumentsElement = (
        <div className="func--arguments">
            <p className="func--text">Arguments</p>
            {
                inputs[0]
                    ? <>{inputsList}</>
                    : <p className="func--argument">none</p>
            }
        </div>)

    const exampleCode = example
        ? <div className="func--code func--text courier">
            {example}
        </div>
        : ""

    const tableHeaders = table
        ? (
            <thead>
                <tr>
                    {table[0]?.headers.map(header => {
                        return (
                            <th key={header} >
                                {header}
                            </th>
                        )
                    })}
                </tr>
            </thead>
        )
        : ""
    const tableData = table
        ? (
            <tbody>
                {table[0]?.data.map(data => {
                    const content = data.map(content => {
                        return (
                            <td key={content} >
                                {content}
                            </td>
                        )
                    })

                    return (
                        <tr key={data[0]}>
                            {content}
                        </tr>
                    )
                })}
            </tbody>
        )
        : ""

    const tableElement = table 
        ? <div className="func--table">
            <table className="func--text">
                {tableHeaders}
                {tableData}
            </table> 
        </div>
        : ""

    return (
        <div className="func" style={funcStyle}>
            {headerElement}

            {backElement}
            
            {exampleElement}

            {argumentsElement}

            {descriptionElement}

            {tableElement}

            {exampleCode}
            
            {tagField}
        </div>
    )
}